import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
try{
const page=await browser.newPage({viewport:{width:390,height:844}});await page.clock.install();await page.goto('http://127.0.0.1:5178/game027.html');await page.getByRole('button',{name:'許可しない',exact:true}).click();await page.locator('#play-button').click();await page.locator('#power').fill('0');
for(let i=1;i<=10;i++){await page.locator('#shoot-button').click();await page.clock.runFor(2000);const state=await page.evaluate(()=>window.__game027);if(state.challenge.shots!==i)throw Error(`shot${i}: ${state.phase}, ${state.challenge.shots}`);}
await page.locator('#menu-title').filter({hasText:'10球チャレンジ 完了'}).waitFor();const result=await page.evaluate(()=>({challenge:window.__game027.challenge,stats:window.__game027.saved.stats,phase:window.__game027.phase,text:document.querySelector('#menu').textContent}));if(result.stats.games!==0)throw Error('challenge altered standard match stats');await page.screenshot({path:'docs/game027/mobile-20261104/QA/challenge-result.png'});writeFileSync('docs/game027/mobile-20261104/QA/challenge-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));await page.close();
const echo=await browser.newPage({viewport:{width:390,height:844}});await echo.clock.install({time:new Date('2026-11-04T00:00:00Z')});await echo.clock.pauseAt(new Date('2026-11-04T00:00:01Z'));await echo.goto('http://127.0.0.1:5179/game051.html');await echo.locator('#play').click();await echo.locator('#guide-next').click();await echo.locator('#guide-next').click();await echo.locator('#guide-play').click();
for(let round=0;round<3;round++)for(let take=0;take<3;take++){await echo.clock.runFor(1000);await echo.locator(`#lane-${take}`).click();await echo.clock.runFor(1500);await echo.locator(`#lane-${take}`).click();await echo.clock.runFor(1500);await echo.locator(`#lane-${take}`).click();await echo.clock.runFor(1000);}
await echo.clock.runFor(100);await echo.locator('#retry').waitFor();const echoResult=await echo.locator('.card').innerText();if(!echoResult.includes('S')||!echoResult.includes('最高×4'))throw Error(echoResult);await echo.screenshot({path:'docs/game051/mobile-20261104/QA/combo-result.png'});writeFileSync('docs/game051/mobile-20261104/QA/combo-result.json',JSON.stringify({provenance:'ordinary pointer clicks with browser clock, no game state injection',text:echoResult},null,2));console.log(echoResult);
}finally{await browser.close();}
